# Serves real anisette headers from this Mac's AOSKit, for the bridge on snek3.
#
# Since Oct 2026 Apple rejects GrandSlam logins that use anisette from the public remote
# servers (-80045). Headers generated by a real Mac still work, so the bridge asks this.
# Same fields as omnisette's AOSKitAnisetteProvider (omnisette/src/aos_kit.rs).
#
# Python 2.7 + PyObjC: what Catalina ships in /usr/bin/python, so nothing is installed.
# GET / with header "Authorization: Bearer <token>" -> JSON map of headers.
import BaseHTTPServer
import datetime
import json
import os
import re
import sys

import objc  # noqa: F401  (loads the bridge so NSClassFromString works)
from Foundation import NSBundle, NSClassFromString

NSBundle.bundleWithPath_("/System/Library/PrivateFrameworks/AOSKit.framework").load()
NSBundle.bundleWithPath_("/System/Library/PrivateFrameworks/AuthKit.framework").load()
AOSUtilities = NSClassFromString("AOSUtilities")
AKDevice = NSClassFromString("AKDevice")

TOKEN = open(os.path.expanduser("~/.imassage-anisette-token")).read().strip()
PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 6969


def headers():
    otp = AOSUtilities.retrieveOTPHeadersForDSID_("-2")
    dev = AKDevice.currentDevice()
    return {
        "X-Apple-I-MD": otp["X-Apple-MD"],
        "X-Apple-I-MD-M": otp["X-Apple-MD-M"],
        "X-Apple-I-MD-RINFO": "17106176",
        "X-Apple-I-MD-LU": dev.localUserUUID(),
        "X-Apple-SRL-NO": AOSUtilities.machineSerialNumber(),
        "X-Mme-Device-Id": dev.uniqueDeviceIdentifier(),
        # The description names the calling process (python); present as akd, as the real one does.
        "X-Mme-Client-Info": re.sub(r"\([^()]*\)>$", "(com.apple.akd/1.0)>", dev.serverFriendlyDescription()),
        "X-Apple-Locale": "en_US",
        "X-Apple-I-TimeZone": "UTC",
        "X-Apple-I-Client-Time": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
    }


class Handler(BaseHTTPServer.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.headers.get("Authorization") != "Bearer " + TOKEN:
            self.send_response(403)
            self.end_headers()
            return
        try:
            body = json.dumps(dict((k, unicode(v)) for k, v in headers().items()))
        except Exception as e:  # keep serving; the bridge retries
            self.send_response(500)
            self.end_headers()
            self.wfile.write(str(e))
            return
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, fmt, *args):
        sys.stderr.write("%s %s\n" % (self.log_date_time_string(), fmt % args))


BaseHTTPServer.HTTPServer(("0.0.0.0", PORT), Handler).serve_forever()
